INSERT INTO `lfg_dungeons_locale` VALUES (1533,'deDE','Zeitwanderungsschlachtzug: Der Schwarze Tempel','',69497),(1533,'esES','Banda de Paseo en el tiempo: Templo Oscuro','',69497),(1533,'esMX','Banda de cronoviaje: Templo Oscuro','',69497),(1533,'frFR','Raid des marcheurs du temps : Temple noir','',69497),(1533,'itIT','Incursione nel Tempo: Tempio Nero','',69497),(1533,'koKR','시간여행 공격대: 검은 사원','',69497),(1533,'ptBR','Raide de Caminhada Temporal: Templo Negro','',69497),(1533,'ruRU','Путешествие во времени, рейд: Черный храм','',69497),(1533,'zhCN','时空漫游团队副本：黑暗神殿','',69497),(1533,'zhTW','時光漫遊團隊副本：黑暗神廟','',69497),(1677,'deDE','Zeitwanderungsschlachtzug: Ulduar','',69497),(1677,'esES','Banda de Paseo en el tiempo: Ulduar','',69497),(1677,'esMX','Banda de cronoviaje: Ulduar','',69497),(1677,'frFR','Raid des marcheurs du temps : Ulduar','',69497),(1677,'itIT','Incursione nel Tempo: Ulduar','',69497),(1677,'koKR','시간여행 공격대: 울두아르','',69497),(1677,'ptBR','Raide de Caminhada Temporal: Ulduar','',69497),(1677,'ruRU','Путешествие во времени, рейд: Ульдуар','',69497),(1677,'zhCN','时空漫游团队副本：奥杜尔','',69497),(1677,'zhTW','時光漫遊團隊副本：奧杜亞','',69497),(1917,'deDE','Sturz des Betrügers','In den Tiefen des Grabmals des Sargeras scheint Kil\'jaeden endlich in der Falle zu sitzen. Oder spielen wir dem Betrüger direkt in die Hände?',69497),(1917,'esES','Caída del Impostor','Parece que Kil\'jaeden al fin está confinado en las profundidades de la Tumba de Sargeras. ¿O será otra artimaña del Impostor?',69497),(1917,'esMX','La caída del Falsario','Parece que Kil\'jaeden finalmente está atrapado en las profundidades de la Tumba de Sargeras. ¿O solo somos marionetas en manos del Falsario?',69497),(1917,'frFR','La chute du Trompeur','Dans les profondeurs de la tombe, Kil’jaeden semble enfin piégé… Ou alors c’est ce qu’il tente nous faire croire.',69497),(1917,'itIT','Caduta dell\'Ingannatore','Nelle profondità della Tomba di Sargeras, Kil\'jaeden sembra alle strette... o forse è solo un altro tranello dell\'Ingannatore?',69497),(1917,'koKR','기만자의 몰락','살게라스의 무덤 깊은 곳에서 드디어 킬제덴이 궁지에 몰린 듯 보입니다. 아니면, 기만자의 수법에 모두가 놀아나는 것일까요?',69497),(1917,'ptBR','Queda do Enganador','Nas profundezas da Tumba de Sargeras, Kil\'jaeden parece enfim encurralado. Ou estamos apenas sendo ludibriados pelo Enganador?',69497),(1917,'ruRU','Падение Искусителя','Похоже, Кил\'джеден загнан в угол в глубине гробницы. Победа? Или все это время мы были лишь пешками в игре Искусителя?',69497),(1917,'zhCN','欺诈者之陨','在萨格拉斯之墓的深处，基尔加丹似乎终于走投无路了。但这是真的吗？还是我们落入了欺诈者的陷阱？',69497),(1917,'zhTW','欺詐者末路','薩格拉斯之墓深處，基爾加丹似乎被逼到了絕境。又或者，這一切都只是欺詐者的精心安排？',69497),(1918,'deDE','Kammer des Avatars','Aegwynn schloss den besiegten Avatar von Sargeras einst in den Tiefen des Grabmals ein. Doch die gefürchtete Hülle beginnt sich zu regen...',69497),(1918,'esES','Cámara del Avatar','Aegwynn selló bajo la Tumba al Avatar de Sargeras derrotado, pero ahora parece que esa criatura aterradora está despertando...',69497),(1918,'esMX','Cámara del Avatar','Aegwynn encerró al Avatar derrotado de Sargeras en las profundidades de la Tumba, pero ahora el aterrador caparazón ha comenzado a agitarse...',69497),(1918,'frFR','Chambre de l’Avatar','Aegwynn avait enfermé l’Avatar de Sargeras dans les profondeurs de la tombe, mais la terrible enveloppe commence à s’agiter…',69497),(1918,'itIT','Sala dell\'Avatar','Aegwynn ha sigillato lo sconfitto Avatar di Sargeras nelle profondità della Tomba, ma la struttura inizia a cedere...',69497),(1918,'koKR','화신의 방','에이그윈은 살게라스의 화신을 무덤 깊은 곳에 봉인했으나, 그 무시무시한 껍질이 다시 꿈틀거리기 시작합니다...',69497),(1918,'ptBR','Câmara do Avatar','Aegwynn trancafiou o Avatar de Sargeras derrotado nas profundezas da Tumba, mas a temível carcaça lentamente começa a se mover...',69497),(1918,'ruRU','Зал аватары','Эгвин заперла побежденную аватару Саргераса в глубинах гробницы, но недавно оболочка падшего титана начала пробуждаться...',69497),(1918,'zhCN','化身密室','艾格文击败萨格拉斯的化身后，将他封印在了陵墓深处，但那具恐怖的躯壳现在又开始活动了……',69497),(1918,'zhTW','化身密室','艾格文擊敗薩格拉斯的化身之後，將他封印在古墓的深處。如今，恐怖的軀殼再次開始騷動…',69497),(1919,'deDE','Klagende Hallen','Die tieferen Ebenen des einstigen Tempels von Elune wurden vor Generationen versiegelt und haben undenkbare Schrecken hervorgebracht.',69497),(1919,'esES','Cámaras de los Lamentos','Las recónditas profundidades del que fuera el Templo de Elune llevan generaciones selladas, engendrando horrores inimaginables.',69497),(1919,'esMX','Salones de los lamentos','Los confines inferiores del otrora Templo de Elune estuvieron sellados por generaciones, y allí se han engendrado horrores inimaginables.',69497),(1919,'frFR','Salles des Lamentations','Les tréfonds de l’ancien temple d’Élune, scellés depuis des générations, ont vu naître des horreurs inimaginables.',69497),(1919,'itIT','Sale dei Lamenti','Le profondità più oscure dell\'antico Tempio di Elune sono state sigillate secoli fa per contenere la proliferazione di orrori.',69497),(1919,'koKR','통곡의 전당','한때 엘룬의 사원이었던 곳의 하층부는 몇 세대 동안 봉인된 채, 상상을 초월하는 괴물들을 만들어 냈습니다.',69497),(1919,'ptBR','Salões Ululantes','As áreas inferiores do antigo Templo de Eluna permaneceram seladas por longas gerações, gerando horrores impensáveis.',69497),(1919,'ruRU','Залы Стенаний','Нижние ярусы бывшего храма Элуны много веков были изолированы от внешнего мира, породив множество невообразимых ужасов.',69497),(1919,'zhCN','哀嚎大厅','昔日月神殿的下层区域，已经被封印了数代，滋生着难以想象的恐怖。',69497),(1919,'zhTW','哀嚎大廳','曾是伊露恩神殿下層的地區，已被封印數百年之久。那裡的黑暗中產生了無法想像的恐怖生物。',69497),(1920,'deDE','Tore der Hölle','Nach Wochen erbitterter Kämpfe setzen die Helden von Azeroth endlich Fuß in das dunkle Grabmal, aber die Legion hat auch einige Vorbereitungen getroffen...',69497),(1920,'esES','Las Puertas del Infierno','Tras semanas de dura batalla, los héroes de Azeroth acceden por fin a la Tumba oscura, pero la Legión tampoco ha estado ociosa...',69497),(1920,'esMX','Las puertas del infierno','Después de semanas de arduas batallas, los héroes de Azeroth por fin han entrado en la Tumba oscura, pero la Legión también ha estado preparándose...',69497),(1920,'frFR','Les portes de l’enfer','Après des semaines de dur combat, les héros d’Azeroth pénètrent enfin dans la tombe, mais la Légion les attend de pied ferme…',69497),(1920,'itIT','I cancelli dell\'inferno','Dopo settimane di duri scontri, gli eroi di Azeroth sono penetrati nella Tomba, ma la Legione non si farà cogliere di sorpresa.',69497),(1920,'koKR','지옥의 관문','몇 주에 걸친 고된 싸움 끝에, 아제로스의 영웅들은 드디어 어두운 무덤에 들어갑니다. 그러나 군단도 대비하고 있었습니다...',69497),(1920,'ptBR','Os Portões do Inferno','Após semanas em uma dura batalha, os heróis de Azeroth por fim adentram a Tumba sombria, mas a Legião também se preparou...',69497),(1920,'ruRU','Врата ада','После долгих недель сражений герои Азерота наконец-то проникли в Гробницу Саргераса – но и Легион тоже не сидел сложа руки...',69497),(1920,'zhCN','地狱之门','经过数周的艰苦奋战，艾泽拉斯的英雄们终于进入了黑暗的萨格拉斯之墓，但燃烧军团早有准备……',69497),(1920,'zhTW','地獄之門','歷經了數週的苦戰，艾澤拉斯的英雄們終於進入黑暗的薩格拉斯之墓，但燃燒軍團也早已做了準備…',69497),(2026,'deDE','Zeitwanderungsschlachtzug: Die Feuerlande','',69497),(2026,'esES','Banda de Paseo en el tiempo: Tierras de Fuego','',69497),(2026,'esMX','Banda de cronoviaje: Tierras de Fuego','',69497),(2026,'frFR','Raid des marcheurs du temps : terres de Feu','',69497),(2026,'itIT','Incursione nel Tempo: Terre del Fuoco','',69497),(2026,'koKR','시간여행 공격대: 불의 땅','',69497),(2026,'ptBR','Raide de Caminhada Temporal: Terras do Fogo','',69497),(2026,'ruRU','Путешествие во времени, рейд: Огненные Просторы','',69497),(2026,'zhCN','时空漫游团队副本：火焰之地','',69497),(2026,'zhTW','時光漫遊團隊副本：火源之界','',69497),(3116,'deDE','Sitz des Triumvirats','',69497),(3116,'esES','Trono del Triunvirato','',69497),(3116,'esMX','Trono del Triunvirato','',69497),(3116,'frFR','Siège du triumvirat','',69497),(3116,'itIT','Seggio del Triumvirato','',69497),(3116,'koKR','삼두정의 권좌','',69497),(3116,'ptBR','Sede do Triunvirato','',69497),(3116,'ruRU','Престол Триумвирата','',69497),(3116,'zhCN','执政团之座','',69497),(3116,'zhTW','三傑議會之座','',69497),(3119,'deDE','Akademie von Alge